"""Summarize the Codex app-server JSON schema generated by:

    codex app-server generate-json-schema --out docs/codex-schema

Usage:
    py -3 tools/schema_summary.py methods
    py -3 tools/schema_summary.py top v2/TurnStartParams.json [more files...]
    py -3 tools/schema_summary.py defs v2/TurnCompletedNotification.json Turn TurnStatus
"""
import json
import os
import sys

BASE = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "docs", "codex-schema")
REF = "$" + "ref"


def load(name):
    with open(os.path.join(BASE, name.replace("/", os.sep)), encoding="utf-8") as fh:
        return json.load(fh)


def short(s, depth=0):
    if not isinstance(s, dict):
        return str(s)
    if REF in s:
        return s[REF].split("/")[-1]
    if "enum" in s:
        return "enum" + json.dumps(s["enum"])
    for key in ("anyOf", "oneOf", "allOf"):
        if key in s:
            return " | ".join(short(x, depth + 1) for x in s[key])
    t = s.get("type")
    if t == "array":
        return "array<" + short(s.get("items", {}), depth + 1) + ">"
    if t == "object" and "properties" in s and depth < 2:
        inner = ", ".join("%s: %s" % (k, short(v, depth + 1)) for k, v in s["properties"].items())
        return "{" + inner + "}"
    return json.dumps(t)


def methods():
    for name in ("ClientRequest.json", "ClientNotification.json", "ServerRequest.json", "ServerNotification.json"):
        doc = load(name)
        found = []
        for variant in doc.get("oneOf", []) + doc.get("anyOf", []):
            m = variant.get("properties", {}).get("method", {})
            values = m.get("enum") or ([m["const"]] if "const" in m else None)
            if values:
                found.append(values[0])
        print("=== %s (%d) ===" % (name, len(found)))
        print(", ".join(found))


def top(names):
    for name in names:
        try:
            doc = load(name)
        except OSError as exc:
            print("ERR", name, exc)
            continue
        print("=== %s  required=%s" % (name, doc.get("required")))
        for key, value in doc.get("properties", {}).items():
            print("    %s: %s" % (key, short(value)))
        if "oneOf" in doc or "anyOf" in doc:
            for variant in doc.get("oneOf", []) + doc.get("anyOf", []):
                print("    variant: %s" % short(variant))


def defs(name, wanted):
    doc = load(name)
    table = doc.get("definitions", {})
    for key in wanted:
        d = table.get(key)
        print("--- %s :: %s" % (name, key))
        if d is None:
            print("    (not defined here; available: %s)" % ", ".join(sorted(table))[:1500])
            continue
        if "enum" in d:
            print("    enum %s" % json.dumps(d["enum"]))
        for k, v in d.get("properties", {}).items():
            print("    %s: %s" % (k, short(v)))
        if d.get("required"):
            print("    required=%s" % d["required"])
        for variant in d.get("oneOf", []) + d.get("anyOf", []):
            title = variant.get("title", "")
            if "properties" in variant:
                inner = ", ".join("%s: %s" % (k, short(v, 1)) for k, v in variant["properties"].items())
                print("    variant %s {%s}" % (title, inner))
            else:
                print("    variant %s %s" % (title, short(variant)))


if __name__ == "__main__":
    args = sys.argv[1:]
    if not args or args[0] == "methods":
        methods()
    elif args[0] == "top":
        top(args[1:])
    elif args[0] == "defs":
        defs(args[1], args[2:])
    else:
        print(__doc__)
